//! Brand icon SVG path data (24x24 viewBox) from simple-icons (CC0).
//! Generated; used by the `render` feature to draw logos onto keys.

/// Guess a brand id from a free-text key label (e.g. "Open Spotify" -> spotify).
pub fn brand_for_label(label: &str) -> Option<&'static str> {
    let l = label.to_lowercase();
    if l.contains("spotify") {
        Some("spotify")
    } else if l.contains("steam") {
        Some("steam")
    } else if l.contains("discord") {
        Some("discord")
    } else if l.contains("battle") {
        Some("battlenet")
    } else if l.contains("claude") {
        Some("claude")
    } else {
        None
    }
}

/// Look up a brand icon path by profile id.
pub fn brand_path(id: &str) -> Option<&'static str> {
    Some(match id {
        "spotify" => SPOTIFY,
        "steam" => STEAM,
        "discord" => DISCORD,
        "battlenet" => BATTLENET,
        "claude" => CLAUDE,
        _ => return None,
    })
}

